import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {auditCallback} from '../src/routes/orders.ts';
import {unrelatedHelper, documentation} from '../src/routes/accounts.ts';

test('routes are registered in expected order and count', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({method: r.method, path: r.path})),
    [
      {method: 'GET', path: '/accounts/:id'},
      {method: 'POST', path: '/accounts'},
      {method: 'GET', path: '/health'},
      {method: 'GET', path: '/orders/:id'},
      {method: 'DELETE', path: '/orders/:id'},
    ]
  );
});

test('GET /accounts/:id success returns response and does not call next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
  assert.ok(route);
  let nextCalled = false;
  const res = { send: v => `sent:${v}` };
  const result = await route.handler({ id: 'acc1' }, res, () => { nextCalled = true; });
  assert.equal(result, 'sent:account:acc1');
  assert.equal(nextCalled, false);
});

test('GET /accounts/:id failure forwards error to next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
  let capturedError = null;
  const res = { send: v => v };
  await route.handler({ id: 'acc1', fail: true }, res, err => { capturedError = err; });
  assert.ok(capturedError instanceof Error);
  assert.equal(capturedError.message, 'account read');
});

test('POST /accounts success returns response and does not call next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
  assert.ok(route);
  let nextCalled = false;
  const res = { send: v => `sent:${v}` };
  const result = await route.handler({ id: 'acc2' }, res, () => { nextCalled = true; });
  assert.equal(result, 'sent:created:acc2');
  assert.equal(nextCalled, false);
});

test('POST /accounts failure forwards error to next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
  let capturedError = null;
  const res = { send: v => v };
  await route.handler({ id: 'acc2', fail: true }, res, err => { capturedError = err; });
  assert.ok(capturedError instanceof Error);
  assert.equal(capturedError.message, 'account create');
});

test('GET /health synchronous route is preserved and returns response', () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/health');
  assert.ok(route);
  let nextCalled = false;
  const res = { send: v => `sent:${v}` };
  const result = route.handler({ id: 'none' }, res, () => { nextCalled = true; });
  assert.equal(result, 'sent:ok');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id success returns uppercase order id and does not call next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
  assert.ok(route);
  let nextCalled = false;
  const res = { send: v => `sent:${v}` };
  const result = await route.handler({ id: 'ord123' }, res, () => { nextCalled = true; });
  assert.equal(result, 'sent:ORD123');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id failure forwards error to next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
  let capturedError = null;
  const res = { send: v => v };
  await route.handler({ id: 'ord123', fail: true }, res, err => { capturedError = err; });
  assert.ok(capturedError instanceof Error);
  assert.equal(capturedError.message, 'order read');
});

test('DELETE /orders/:id success returns response and does not call next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
  assert.ok(route);
  let nextCalled = false;
  const res = { send: v => `sent:${v}` };
  const result = await route.handler({ id: 'ord999' }, res, () => { nextCalled = true; });
  assert.equal(result, 'sent:deleted:ord999');
  assert.equal(nextCalled, false);
});

test('DELETE /orders/:id failure forwards error to next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
  let capturedError = null;
  const res = { send: v => v };
  await route.handler({ id: 'ord999', fail: true }, res, err => { capturedError = err; });
  assert.ok(capturedError instanceof Error);
  assert.equal(capturedError.message, 'order delete');
});

test('unrelated helpers and audit callbacks are untouched', async () => {
  assert.equal(documentation, "router.get('/fake', async handler)");
  await assert.rejects(async () => { await unrelatedHelper(); }, { message: 'helper' });
  await assert.rejects(async () => { await auditCallback(); }, { message: 'audit' });
});

